package com.justjava.humanresource.employeeexit.service; import com.justjava.humanresource.approval.enums.ApprovalModuleType; import com.justjava.humanresource.approval.model.ApprovalContext; import com.justjava.humanresource.employeeexit.entity.EmployeeExitCase; import org.springframework.stereotype.Component;
@Component public class ExitApprovalContextFactory { public ApprovalContext create(EmployeeExitCase x){return ApprovalContext.builder().moduleType(ApprovalModuleType.EXIT).routeType(x.getApprovalRouteType()).requesterEmployeeId(x.getEmployeeId()).moduleRefId(x.getId()).requestTypeCode(x.getExitType().name()).customApprovalPathId(x.getCustomApprovalPathId()).build();} }
